<script>
/* ============================================================
   WASTEDTOKEN MINT — hero coin (WebGL) + edition canvases (2D)
   ============================================================ */

/* ---------- 2D coin renderer for edition tiles ---------- */
function drawCoin2D(ctx, size, palette){
  const cx=size/2, cy=size/2, r=size*0.46;
  ctx.clearRect(0,0,size,size);

  // background
  const bg = ctx.createRadialGradient(cx,cy,r*0.2,cx,cy,r*1.3);
  bg.addColorStop(0, palette.bgInner);
  bg.addColorStop(1, palette.bgOuter);
  ctx.fillStyle=bg; ctx.fillRect(0,0,size,size);

  // outer rim shadow
  ctx.save();
  ctx.beginPath(); ctx.arc(cx,cy,r*1.02,0,Math.PI*2);
  ctx.fillStyle='rgba(0,0,0,0.55)'; ctx.fill();
  ctx.restore();

  // coin body gradient
  const g = ctx.createRadialGradient(cx-r*0.35, cy-r*0.4, r*0.1, cx, cy, r);
  g.addColorStop(0, palette.hi);
  g.addColorStop(0.45, palette.mid);
  g.addColorStop(1, palette.lo);
  ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2);
  ctx.fillStyle=g; ctx.fill();

  // reeded edge
  ctx.save();
  ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.clip();
  for(let i=0;i<120;i++){
    const a=i/120*Math.PI*2;
    const x1=cx+Math.cos(a)*r*0.93, y1=cy+Math.sin(a)*r*0.93;
    const x2=cx+Math.cos(a)*r*1.01, y2=cy+Math.sin(a)*r*1.01;
    ctx.strokeStyle = i%2? palette.edgeHi : palette.edgeLo;
    ctx.lineWidth=1.2;
    ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
  }
  ctx.restore();

  // inner ring
  ctx.beginPath(); ctx.arc(cx,cy,r*0.82,0,Math.PI*2);
  ctx.strokeStyle=palette.ring; ctx.lineWidth=1.5; ctx.stroke();
  ctx.beginPath(); ctx.arc(cx,cy,r*0.78,0,Math.PI*2);
  ctx.strokeStyle=palette.ring; ctx.lineWidth=0.8; ctx.stroke();

  // central emblem: stylized "W" monogram
  ctx.save();
  ctx.translate(cx,cy);
  // emblem background disc
  const eg = ctx.createRadialGradient(-r*0.1,-r*0.15,r*0.05,0,0,r*0.55);
  eg.addColorStop(0, palette.hi);
  eg.addColorStop(1, palette.mid);
  ctx.beginPath(); ctx.arc(0,0,r*0.55,0,Math.PI*2);
  ctx.fillStyle=eg; ctx.fill();

  // "W" letter
  ctx.fillStyle=palette.letter;
  ctx.font = `bold ${r*0.9}px Georgia, serif`;
  ctx.textAlign='center'; ctx.textBaseline='middle';
  ctx.fillText('W', 0, r*0.05);

  // small star above
  ctx.fillStyle=palette.letter;
  ctx.beginPath();
  const sy=-r*0.42;
  for(let i=0;i<10;i++){
    const a=-Math.PI/2 + i*Math.PI/5;
    const rr = i%2? r*0.04 : r*0.09;
    const x=Math.cos(a)*rr, y=sy+Math.sin(a)*rr;
    if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
  }
  ctx.closePath(); ctx.fill();

  // curved text around
  ctx.fillStyle=palette.letter;
  ctx.font = `${r*0.1}px Georgia, serif`;
  const topText="WASTEDTOKEN · MINT ·";
  const botText="· CHALLENGE · COIN ·";
  drawArcText(ctx, topText, 0, 0, r*0.68, -Math.PI/2, true);
  drawArcText(ctx, botText, 0, 0, r*0.68, Math.PI/2, false);

  ctx.restore();

  // specular highlight sweep
  const sg = ctx.createLinearGradient(cx-r, cy-r, cx+r*0.3, cy+r*0.3);
  sg.addColorStop(0,'rgba(255,255,255,0)');
  sg.addColorStop(0.45,'rgba(255,255,255,0)');
  sg.addColorStop(0.55, palette.spec);
  sg.addColorStop(0.65,'rgba(255,255,255,0)');
  sg.addColorStop(1,'rgba(255,255,255,0)');
  ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2);
  ctx.fillStyle=sg; ctx.fill();
}
function drawArcText(ctx,text,cx,cy,r,center,top){
  const chars=text.split('');
  const total=chars.length;
  const span=Math.PI*0.9;
  for(let i=0;i<total;i++){
    const t = (i/(total-1))-0.5;
    let a = center + t*span;
    if(!top) a = center + Math.PI - t*span;
    const x=cx+Math.cos(a)*r, y=cy+Math.sin(a)*r;
    ctx.save();
    ctx.translate(x,y);
    ctx.rotate(a + (top? Math.PI/2 : -Math.PI/2));
    ctx.fillText(chars[i],0,0);
    ctx.restore();
  }
}

const palettes = {
  bronze:{bgInner:'#2a1a0c',bgOuter:'#0a0604',hi:'#e8b06a',mid:'#a06a2c',lo:'#4a2a10',
          edgeHi:'#d89a52',edgeLo:'#3a2008',ring:'#6a3e14',letter:'#3a1e08',spec:'rgba(255,220,160,0.35)'},
  silver:{bgInner:'#2a2a30',bgOuter:'#08080a',hi:'#f0f0f4',mid:'#a8a8b0',lo:'#404048',
          edgeHi:'#d8d8dc',edgeLo:'#2a2a30',ring:'#606068',letter:'#202028',spec:'rgba(255,255,255,0.5)'},
  gold:  {bgInner:'#3a2a08',bgOuter:'#0a0602',hi:'#ffe27a',mid:'#d4a030',lo:'#5a3a08',
          edgeHi:'#f4c850',edgeLo:'#3a2408',ring:'#7a5010',letter:'#3a2004',spec:'rgba(255,240,180,0.45)'},
  black: {bgInner:'#1a1a1e',bgOuter:'#040406',hi:'#5a5a64',mid:'#22222a',lo:'#08080c',
          edgeHi:'#3a3a44',edgeLo:'#0a0a10',ring:'#2a2a32',letter:'#c8c8d0',spec:'rgba(200,200,220,0.25)'}
};

document.querySelectorAll('.edition').forEach(el=>{
  const ed = el.dataset.edition;
  const c = el.querySelector('.edition-canvas');
  const ctx = c.getContext('2d');
  drawCoin2D(ctx, c.width, palettes[ed]);
});

/* ============================================================
   HERO COIN — WebGL
   ============================================================ */
(function(){
  const canvas = document.getElementById('coin-hero');
  const gl = canvas.getContext('webgl', {antialias:true, premultipliedAlpha:false});
  if(!gl){ return; }

  /* ---------- build procedural textures for front & back ---------- */
  function makeFaceTex(drawFn, size){
    const c = document.createElement('canvas');
    c.width=c.height=size;
    const ctx=c.getContext('2d');
    drawFn(ctx,size);
    return c;
  }

  // FRONT face: emblem
  const frontCanvas = makeFaceTex((ctx,S)=>{
    // base metal
    const g = ctx.createRadialGradient(S*0.35,S*0.35,S*0.05,S/2,S/2,S*0.55);
    g.addColorStop(0,'#f0d080');
    g.addColorStop(0.5,'#c89040');
    g.addColorStop(1,'#6a4018');
    ctx.fillStyle=g; ctx.fillRect(0,0,S,S);

    const cx=S/2, cy=S/2, r=S*0.48;

    // outer ring
    ctx.strokeStyle='#3a2008'; ctx.lineWidth=S*0.012;
    ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.stroke();
    ctx.beginPath(); ctx.arc(cx,cy,r*0.92,0,Math.PI*2); ctx.stroke();

    // inner disc (slightly darker for embossed contrast)
    const ig = ctx.createRadialGradient(cx-r*0.2,cy-r*0.25,r*0.05,cx,cy,r*0.85);
    ig.addColorStop(0,'#e8c070');
    ig.addColorStop(1,'#8a5820');
    ctx.beginPath(); ctx.arc(cx,cy,r*0.85,0,Math.PI*2);
    ctx.fillStyle=ig; ctx.fill();

    // big W
    ctx.fillStyle='#2a1404';
    ctx.font = `bold ${S*0.42}px Georgia, serif`;
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('W', cx, cy+S*0.02);

    // highlight on W (emboss)
    ctx.fillStyle='rgba(255,230,170,0.35)';
    ctx.fillText('W', cx-S*0.005, cy+S*0.015);

    // star above
    ctx.fillStyle='#2a1404';
    ctx.beginPath();
    const sy=cy-r*0.55;
    for(let i=0;i<10;i++){
      const a=-Math.PI/2 + i*Math.PI/5;
      const rr = i%2? S*0.015 : S*0.035;
      const x=cx+Math.cos(a)*rr, y=sy+Math.sin(a)*rr;
      if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
    }
    ctx.closePath(); ctx.fill();

    // curved text
    ctx.fillStyle='#2a1404';
    ctx.font = `${S*0.042}px Georgia, serif`;
    drawArcText(ctx,"WASTEDTOKEN · MINT ·",cx,cy,r*0.78,-Math.PI/2,true);
    drawArcText(ctx,"· CHALLENGE · COIN ·",cx,cy,r*0.78,Math.PI/2,false);

    // small dots around rim
    for(let i=0;i<40;i++){
      const a=i/40*Math.PI*2;
      ctx.beginPath();
      ctx.arc(cx+Math.cos(a)*r*0.96, cy+Math.sin(a)*r*0.96, S*0.005, 0, Math.PI*2);
      ctx.fillStyle='#2a1404'; ctx.fill();
    }
  }, 512);

  // BACK face: denomination
  const backCanvas = makeFaceTex((ctx,S)=>{
    const g = ctx.createRadialGradient(S*0.35,S*0.35,S*0.05,S/2,S/2,S*0.55);
    g.addColorStop(0,'#f0d080');
    g.addColorStop(0.5,'#c89040');
    g.addColorStop(1,'#6a4018');
    ctx.fillStyle=g; ctx.fillRect(0,0,S,S);

    const cx=S/2, cy=S/2, r=S*0.48;

    ctx.strokeStyle='#3a2008'; ctx.lineWidth=S*0.012;
    ctx.beginPath(); ctx.arc(cx,cy,r,0,Math.PI*2); ctx.stroke();
    ctx.beginPath(); ctx.arc(cx,cy,r*0.92,0,Math.PI*2); ctx.stroke();

    const ig = ctx.createRadialGradient(cx-r*0.2,cy-r*0.25,r*0.05,cx,cy,r*0.85);
    ig.addColorStop(0,'#e8c070');
    ig.addColorStop(1,'#8a5820');
    ctx.beginPath(); ctx.arc(cx,cy,r*0.85,0,Math.PI*2);
    ctx.fillStyle=ig; ctx.fill();

    // big number
    ctx.fillStyle='#2a1404';
    ctx.font = `bold ${S*0.16}px Georgia, serif`;
    ctx.textAlign='center'; ctx.textBaseline='middle';
    ctx.fillText('10,000', cx, cy-S*0.04);

    ctx.font = `${S*0.07}px Georgia, serif`;
    ctx.letterSpacing='4px';
    ctx.fillText('TOKENS', cx, cy+S*0.08);

    // emboss highlight
    ctx.fillStyle='rgba(255,230,170,0.3)';
    ctx.font = `bold ${S*0.16}px Georgia, serif`;
    ctx.fillText('10,000', cx-S*0.004, cy-S*0.045);

    // decorative lines
    ctx.strokeStyle='#2a1404'; ctx.lineWidth=S*0.006;
    ctx.beginPath();
    ctx.moveTo(cx-r*0.55, cy+S*0.15); ctx.lineTo(cx+r*0.55, cy+S*0.15);
    ctx.moveTo(cx-r*0.55, cy-S*0.14); ctx.lineTo(cx+r*0.55, cy-S*0.14);
    ctx.stroke();

    // small text
    ctx.fillStyle='#2a1404';
    ctx.font = `${S*0.03}px Georgia, serif`;
    ctx.fillText('ONE · PHYSICAL · TOKEN', cx, cy+S*0.2);
    ctx.fillText('№ 0001 / 0500', cx, cy-S*0.2);

    // dots
    for(let i=0;i<40;i++){
      const a=i/40*Math.PI*2;
      ctx.beginPath();
      ctx.arc(cx+Math.cos(a)*r*0.96, cy+Math.sin(a)*r*0.96, S*0.005, 0, Math.PI*2);
      ctx.fillStyle='#2a1404'; ctx.fill();
    }
  }, 512);

  // EDGE texture: vertical stripes for reeding
  const edgeCanvas = makeFaceTex((ctx,S)=>{
    const stripes = 80;
    const w = S/stripes;
    for(let i=0;i<stripes;i++){
      const x=i*w;
      const bright = (i%2===0) ? '#d8a858' : '#6a4018';
      ctx.fillStyle=bright;
      ctx.fillRect(x,0,w+1,S);
    }
    // vertical gradient for curvature
    const g = ctx.createLinearGradient(0,0,0,S);
    g.addColorStop(0,'rgba(0,0,0,0.4)');
    g.addColorStop(0.5,'rgba(255,220,160,0.15)');
    g.addColorStop(1,'rgba(0,0,0,0.4)');
    ctx.fillStyle=g; ctx.fillRect(0,0,S,S);
  }, 512);

  function uploadTex(canvasEl){
    const t = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, t);
    gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE, canvasEl);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.generateMipmap(gl.TEXTURE_2D);
    return t;
  }
  const texFront = uploadTex(frontCanvas);
  const texBack  = uploadTex(backCanvas);
  const texEdge  = uploadTex(edgeCanvas);

  /* ---------- build geometry: cylinder with caps ---------- */
  // We'll build three parts: top disc (front), bottom disc (back), side (edge).
  // Each part has its own texture index uniform.
  const SEG = 96;
  const R = 1.0;
  const H = 0.12; // half thickness

  // positions, normals, uvs, faceIndex (0=front,1=back,2=edge)
  const pos=[], nrm=[], uv=[], face=[];

  // Front disc (y = +H, normal +Y)
  pos.push(0,H,0); nrm.push(0,1,0); uv.push(0.5,0.5); face.push(0);
  for(let i=0;i<=SEG;i++){
    const a = i/SEG*Math.PI*2;
    const x=Math.cos(a)*R, z=Math.sin(a)*R;
    pos.push(x,H,z); nrm.push(0,1,0);
    uv.push(0.5+Math.cos(a)*0.5, 0.5+Math.sin(a)*0.5);
    face.push(0);
  }
  // Back disc (y = -H, normal -Y)
  pos.push(0,-H,0); nrm.push(0,-1,0); uv.push(0.5,0.5); face.push(1);
  for(let i=0;i<=SEG;i++){
    const a = -i/SEG*Math.PI*2; // reverse winding
