    // bottom vertex
    pos.push(x,-H,z); nrm.push(nx,0,nz);
    uv.push(i/SEG, 1); face.push(2);
  }

  // indices
  const idx=[];
  // front fan
  for(let i=1;i<=SEG;i++){ idx.push(0, i, i+1); }
