  }

  const posBuf = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,posBuf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(pos), gl.STATIC_DRAW);
  const nrmBuf = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,nrmBuf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(nrm), gl.STATIC_DRAW);
  const uvBuf = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,uvBuf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(uv), gl.STATIC_DRAW);
  const faceBuf = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,faceBuf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(face), gl.STATIC_DRAW);
  const idxBuf = gl.createBuffer(); gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,idxBuf);
  gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(idx), gl.STATIC_DRAW);
  const indexCount = idx.length;

  /* ---------- shaders ---------- */
  const vsSrc = `
    attribute vec3 aPos;
    attribute vec3 aNrm;
    attribute vec2 aUv;
    attribute float aFace;
    uniform mat4 uProj, uView, uModel;
    uniform mat3 uNrmMat;
    varying vec3 vN;
    varying vec3 vP;
    varying vec2 vUv;
    varying float vFace;
    void main(){
      vec4 wp = uModel * vec4(aPos,1.0);
      vP = wp.xyz;
      vN = normalize(uNrmMat * aNrm);
      vUv = aUv;
      vFace = aFace;
      gl_Position = uProj * uView * wp;
    }
  `;
  const fsSrc = `
    precision highp float;
    varying vec3 vN;
    varying vec3 vP;
    varying vec2 vUv;
    varying float vFace;
    uniform sampler2D uTexFront;
    uniform sampler2D uTexBack;
    uniform sampler2D uTexEdge;
    uniform vec3 uEye;
    uniform vec3 uLightDir;

    void main(){
      vec3 N = normalize(vN);
      vec3 V = normalize(uEye - vP);
      vec3 L = normalize(uLightDir);
      vec3 H = normalize(L + V);

      // pick texture
      vec4 tex;
      if(vFace < 0.5){
        tex = texture2D(uTexFront, vUv);
      } else if(vFace < 1.5){
        // back face: mirror UV so text reads correctly when flipped
        tex = texture2D(uTexBack, vec2(1.0 - vUv.x, vUv.y));
      } else {
        tex = texture2D(uTexEdge, vUv);
      }

      // derive bump from luminance gradient (emboss)
      vec2 ts = vec2(1.0/512.0);
      float hC = dot(tex.rgb, vec3(0.33));
      float hR, hU;
      if(vFace < 1.5){
        vec2 uv2 = (vFace<0.5)? vUv : vec2(1.0-vUv.x, vUv.y);
        hR = dot(texture2D(vFace<0.5?uTexFront:uTexBack, uv2+vec2(ts.x,0.0)).rgb, vec3(0.33));
        hU = dot(texture2D(vFace<0.5?uTexFront:uTexBack, uv2+vec2(0.0,ts.y)).rgb, vec3(0.33));
      } else {
        hR = dot(texture2D(uTexEdge, vUv+vec2(ts.x,0.0)).rgb, vec3(0.33));
        hU = dot(texture2D(uTexEdge, vUv+vec2(0.0,ts.y)).rgb, vec3(0.33));
      }
      // perturb normal in tangent space
      vec3 bumpN = N;
      if(vFace < 1.5){
        // approximate tangent frame for Y-up disc
        vec3 up = vec3(0.0,1.0,0.0);
        vec3 T = normalize(cross(up, N));
        if(length(T)<0.001) T = vec3(1.0,0.0,0.0);
