        bumpN = normalize(N + (hC-hR)*T*str + (hC-hU)*B*str);
      } else {
        // edge: tangent along circumference
        vec3 T = normalize(cross(vec3(0.0,1.0,0.0), N));
        vec3 B = vec3(0.0,1.0,0.0);
