      float fres = pow(1.0 - max(dot(N,V),0.0), 3.0);

      // base metallic color from texture
      vec3 base = tex.rgb;

      // environment reflection fake: sample gradient based on reflected view
      vec3 Rv = reflect(-V, N);
      float env = smoothstep(-0.3, 0.9, Rv.y) * 0.5 + 0.3;
      vec3 envCol = mix(vec3(0.15,0.12,0.08), vec3(1.0,0.95,0.85), env);

      vec3 ambient = base * 0.25;
      vec3 diffuse = base * NdL * 0.6;
      vec3 specular = vec3(1.0,0.95,0.8) * spec * 1.4;
      vec3 rim = envCol * fres * 0.5;
      vec3 refl = envCol * 0.25 * (0.5 + 0.5*NdL);

      vec3 col = ambient + diffuse + specular + rim + refl * base;

      // subtle vignette on faces
      if(vFace < 1.5){
        float d = length(vUv - vec2(0.5));
        col *= 1.0 - d*0.3;
      }

      gl_FragColor = vec4(col, 1.0);
    }
  `;

  function compile(type, src){
    const s = gl.createShader(type);
