  const prog = gl.createProgram();
  gl.attachShader(prog, compile(gl.VERTEX_SHADER, vsSrc));
  gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, fsSrc));
  gl.linkProgram(prog);
  if(!gl.getProgramParameter(prog, gl.LINK_STATUS)){
    console.error(gl.getProgramInfoLog(prog));
  }
  gl.useProgram(prog);

  const aPos = gl.getAttribLocation(prog,'aPos');
  const aNrm = gl.getAttribLocation(prog,'aNrm');
  const aUv  = gl.getAttribLocation(prog,'aUv');
  const aFace= gl.getAttribLocation(prog,'aFace');
  gl.bindBuffer(gl.ARRAY_BUFFER,posBuf); gl.enableVertexAttribArray(aPos);
  gl.vertexAttribPointer(aPos,3,gl.FLOAT,false,0,0);
  gl.bindBuffer(gl.ARRAY_BUFFER,nrmBuf); gl.enableVertexAttribArray(aNrm);
  gl.vertexAttribPointer(aNrm,3,gl.FLOAT,false,0,0);
  gl.bindBuffer(gl.ARRAY_BUFFER,uvBuf); gl.enableVertexAttribArray(aUv);
  gl.vertexAttribPointer(aUv,2,gl.FLOAT,false,0,0);
  gl.bindBuffer(gl.ARRAY_BUFFER,faceBuf); gl.enableVertexAttribArray(aFace);
  gl.vertexAttribPointer(aFace,1,gl.FLOAT,false,0,0);
  gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, idxBuf);

  const uProj = gl.getUniformLocation(prog,'uProj');
  const uView = gl.getUniformLocation(prog,'uView');
  const uModel= gl.getUniformLocation(prog,'uModel');
  const uNrmMat=gl.getUniformLocation(prog,'uNrmMat');
  const uEye  = gl.getUniformLocation(prog,'uEye');
  const uLight= gl.getUniformLocation(prog,'uLightDir');
  const uTexF = gl.getUniformLocation(prog,'uTexFront');
  const uTexB = gl.getUniformLocation(prog,'uTexBack');
  const uTexE = gl.getUniformLocation(prog,'uTexEdge');

  gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, texFront); gl.uniform1i(uTexF,0);
  gl.activeTexture(gl.TEXTURE1); gl.bindTexture(gl.TEXTURE_2D, texBack);  gl.uniform1i(uTexB,1);
  gl.activeTexture(gl.TEXTURE2); gl.bindTexture(gl.TEXTURE_2D, texEdge);  gl.uniform1i(uTexE,2);

  gl.enable(gl.DEPTH_TEST);
  gl.enable(gl.CULL_FACE);
  // we want both faces visible; disable cull
  gl.disable(gl.CULL_FACE);

  /* ---------- matrix helpers ---------- */
  function perspective(fovy, aspect, near, far){
    const f = 1/Math.tan(fovy/2);
    const nf = 1/(near-far);
    return new Float32Array([
      f/aspect,0,0,0,
      0,f,0,0,
      0,0,(far+near)*nf,-1,
      0,0,2*far*near*nf,0
