  function mul(a,b){
    const o=new Float32Array(16);
    for(let i=0;i<4;i++)for(let j=0;j<4;j++){
      let s=0; for(let k=0;k<4;k++) s+=a[k*4+j]*b[i*4+k];
      o[i*4+j]=s;
